function battleApiCandidates(mon){const plain=normalizeName(mon.name).replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''),candidates=[String(mon.id),plain],base=plain.split('-mega')[0].split('-gigamax')[0].split('-gmax')[0].replace(/-de-(alola|galar|hisui)$/,'');if(base&&base!==plain)candidates.push(base);if(mon.parent)candidates.push(String(mon.parent));return [...new Set(candidates)];}
