async function enemyLoadout(mon){const learnset=await loadBattleLearnset(mon),keys=defaultMoveKeys(learnset,mon);return{abilityId:mon.abilities[0]||0,moveKeys:keys,learnset};}
async function prepareAndBeginBattle(){if(!battleSelected.every(id=>battleLoadouts.get(id)?.moveKeys.length===4))return;const button=$('start-gym-battle');button.disabled=true;button.textContent='Preparando rival…';const enemyLoadouts=await Promise.all(battleEnemyMons.map(enemyLoadout));if(current!=='battle')return;battlePlayer=battleSelected.map(id=>battleFighter(mons.find(mon=>mon.id===id),'player',battleLoadouts.get(id)));battleEnemy=battleEnemyMons.map((mon,index)=>battleFighter(mon,'enemy',enemyLoadouts[index]));battlePlayerActive=0;battleEnemyActive=0;battleTurn=1;battleField={weather:null,terrain:null,trickRoom:0};battleLog=[`¡El líder ${battleLeader.name} acepta el desafío!`,`Cada Pokémon ataca por separado; la Velocidad decide el orden.`];applyEntryAbility(battleEnemy[0],battlePlayer[0]);applyEntryAbility(battlePlayer[0],battleEnemy[0]);renderBattle();requestAnimationFrame(()=>{gameWindow.scrollTop=0;});}
function battleFighter(mon,side,loadout){const maxHp=battleHp(mon,side),moves=loadout.moveKeys.map(key=>loadout.learnset.moves.find(move=>move.key===key)).filter(Boolean);return{mon,side,maxHp,hp:maxHp,moves,abilityId:Number(loadout.abilityId)||0,status:null,statusTurns:0,stages:{atk:0,def:0,spa:0,spd:0,spe:0,acc:0,eva:0},flinched:false,protected:false,recharging:false,flashFireBoost:false,slowStart:5};}
function hpBar(fighter){const percent=Math.max(0,Math.round(fighter.hp/fighter.maxHp*100)),tone=percent<=25?'danger':percent<=50?'warn':'';return `<div class="battle-hp"><span>PS ${Math.max(0,Math.round(fighter.hp))} / ${fighter.maxHp}</span><progress class="${tone}" max="100" value="${percent}"></progress></div>`;}
function teamDots(team,active){return `<div class="battle-team-dots">${team.map((fighter,index)=>`<span class="${fighter.hp<=0?'fainted':index===active?'active':''}" title="${battleEsc(fighter.mon.name)}">${fighter.hp<=0?'×':'●'}</span>`).join('')}</div>`;}
function battleCondition(fighter){const items=[];if(fighter.status)items.push(BATTLE_AILMENTS[fighter.status]);Object.entries(fighter.stages).forEach(([key,value])=>{if(value)items.push(`${BATTLE_STAT_NAMES[key]} ${value>0?'+':''}${value}`);});return items.length?`<small class="battle-condition">${battleEsc(items.join(' · '))}</small>`:'';}
function renderBattle(){const player=battlePlayer[battlePlayerActive],enemy=battleEnemy[battleEnemyActive];if(!player||!enemy)return;$('score').textContent=String(score).padStart(3,'0');$('progress').textContent=`TURNO ${battleTurn} · ${battlePlayer.filter(f=>f.hp>0).length} VS ${battleEnemy.filter(f=>f.hp>0).length}`;$('game').innerHTML=`<div class="battle-field-status">${battleField.weather?`Clima: ${battleEsc(battleField.weather)}`:'Clima normal'}${battleField.terrain?` · Terreno: ${battleEsc(battleField.terrain)}`:''}${battleField.trickRoom?` · Espacio Raro ${battleField.trickRoom}`:''}</div><div class="battle-action-banner" ${battleBusy?'':'hidden'}>Resolviendo el turno…</div><div class="battle-scene"><section class="battle-side enemy"><div class="battle-info"><small>Líder ${battleEsc(battleLeader.name)}</small><b>${battleEsc(enemy.mon.name)}</b>${typeBadges(enemy.mon)}<em>${battleEsc(battleAbilityName(enemy.abilityId))}</em>${battleCondition(enemy)}${hpBar(enemy)}${teamDots(battleEnemy,battleEnemyActive)}</div><div class="battle-platform"><img src="${spriteUrl(enemy.mon.sprite)}" alt="${battleEsc(enemy.mon.name)}"></div></section><section class="battle-side player"><div class="battle-platform"><img class="back-sprite" src="${battleBackSprite(player.mon)}" data-fallback="${spriteUrl(player.mon.sprite)}" alt="${battleEsc(player.mon.name)} de espaldas"></div><div class="battle-info"><small>Tu Pokémon</small><b>${battleEsc(player.mon.name)}</b>${typeBadges(player.mon)}<em>${battleEsc(battleAbilityName(player.abilityId))}</em>${battleCondition(player)}${hpBar(player)}${teamDots(battlePlayer,battlePlayerActive)}</div></section></div><div class="battle-command"><p>¿Qué debería hacer ${battleEsc(player.mon.name)}?</p><div class="battle-moves"></div><button id="battle-switch" class="battle-switch">Cambiar Pokémon</button></div><div class="battle-log" aria-live="polite">${battleLog.slice(-6).map(line=>`<p>${battleEsc(line)}</p>`).join('')}</div>`;const back=document.querySelector('.back-sprite');back.onerror=()=>{back.onerror=null;back.src=back.dataset.fallback;};const moves=document.querySelector('.battle-moves');player.moves.forEach((move,index)=>{const button=document.createElement('button');button.disabled=battleBusy;button.innerHTML=`<b>${battleEsc(move.name)}</b>${typeBadge(move.type)}<small>${move.category==='status'?'Estado':`Potencia ${move.power}`} · ${move.accuracy?`${move.accuracy}%`:'Nunca falla'}</small>`;button.title=move.description||'';button.onclick=()=>playBattleTurn(index);moves.append(button);});$('battle-switch').disabled=battleBusy||battlePlayer.filter((fighter,index)=>fighter.hp>0&&index!==battlePlayerActive).length===0;$('battle-switch').onclick=renderSwitchMenu;}
function renderSwitchMenu(){const area=document.querySelector('.battle-command');area.innerHTML='<p>Elegí el Pokémon que entra al combate.</p><div class="battle-switches"></div><button id="cancel-switch" class="battle-switch">Cancelar</button>';const options=area.querySelector('.battle-switches');battlePlayer.forEach((fighter,index)=>{if(index===battlePlayerActive||fighter.hp<=0)return;const button=document.createElement('button');button.innerHTML=`<img src="${spriteUrl(fighter.mon.sprite)}" alt=""><span><b>${battleEsc(fighter.mon.name)}</b><small>${battleEsc(battleAbilityName(fighter.abilityId))} · PS ${Math.round(fighter.hp)} / ${fighter.maxHp}</small></span>`;button.onclick=()=>switchBattlePokemon(index);options.append(button);});$('cancel-switch').onclick=renderBattle;}

function changeBattleStage(fighter,key,amount,source=''){if(!key||!amount)return;const blockers=['clear-body','white-smoke','full-metal-body'];if(amount<0&&blockers.includes(battleAbilitySlug(fighter))){battleLog.push(`${battleAbilityName(fighter.abilityId)} evitó la bajada de ${BATTLE_STAT_NAMES[key]}.`);return;}const before=fighter.stages[key],after=Math.max(-6,Math.min(6,before+amount));fighter.stages[key]=after;if(after!==before)battleLog.push(`${BATTLE_STAT_NAMES[key]} de ${fighter.mon.name} ${amount>0?'subió':'bajó'}${Math.abs(amount)>1?' mucho':''}${source?` por ${source}`:''}.`);}
function applyEntryAbility(fighter,foe){const ability=battleAbilitySlug(fighter);if(!ability)return;if(ability==='intimidate')changeBattleStage(foe,'atk',-1,battleAbilityName(fighter.abilityId));if(ability==='drizzle'){battleField.weather='lluvia';battleLog.push(`${fighter.mon.name} hizo llover.`);}if(ability==='drought'){battleField.weather='sol';battleLog.push(`${fighter.mon.name} intensificó el sol.`);}if(ability==='sand-stream'){battleField.weather='tormenta de arena';battleLog.push(`${fighter.mon.name} levantó una tormenta de arena.`);}if(ability==='snow-warning'){battleField.weather='nieve';battleLog.push(`${fighter.mon.name} hizo nevar.`);}const terrains={'electric-surge':'eléctrico','psychic-surge':'psíquico','misty-surge':'de niebla','grassy-surge':'de hierba'};if(terrains[ability]){battleField.terrain=terrains[ability];battleLog.push(`${fighter.mon.name} creó terreno ${terrains[ability]}.`);}if(ability==='download')changeBattleStage(fighter,foe.mon.stats[2]<foe.mon.stats[4]?'atk':'spa',1,'Descarga');if(ability==='trace'&&foe.abilityId){fighter.abilityId=foe.abilityId;battleLog.push(`${fighter.mon.name} copió ${battleAbilityName(foe.abilityId)}.`);}}
function effectiveBattleSpeed(fighter){let speed=fighter.mon.stats[5]*battleStageMultiplier(fighter.stages.spe),ability=battleAbilitySlug(fighter);if(fighter.status===1&&ability!=='quick-feet')speed*=.5;if(ability==='swift-swim'&&battleField.weather==='lluvia')speed*=2;if(ability==='chlorophyll'&&battleField.weather==='sol')speed*=2;if(ability==='sand-rush'&&battleField.weather==='tormenta de arena')speed*=2;if(ability==='slush-rush'&&battleField.weather==='nieve')speed*=2;if(ability==='quick-feet'&&fighter.status)speed*=1.5;if(ability==='slow-start'&&fighter.slowStart>0)speed*=.5;return speed;}
function battleMovePriority(fighter,move){let priority=move.priority||0,ability=battleAbilitySlug(fighter);if(ability==='gale-wings'&&move.type===3&&fighter.hp===fighter.maxHp)priority++;if(ability==='prankster'&&move.category==='status')priority++;return priority;}
function battleMoveType(fighter,move){const ability=battleAbilitySlug(fighter);if(move.type===1&&move.category!=='status'){if(ability==='aerilate')return 3;if(ability==='pixilate')return 18;if(ability==='refrigerate')return 15;if(ability==='galvanize')return 13;}return move.type;}
function effectiveMultiplier(attacker,defender,move){const type=battleMoveType(attacker,move),ability=battleAbilitySlug(defender),breaker=['mold-breaker','teravolt','turboblaze'].includes(battleAbilitySlug(attacker));if(!breaker&&((ability==='levitate'&&type===5)||(['volt-absorb','lightning-rod','motor-drive'].includes(ability)&&type===13)||(['water-absorb','storm-drain','dry-skin'].includes(ability)&&type===11)||(ability==='flash-fire'&&type===10)||(ability==='sap-sipper'&&type===12)))return 0;let multiplier=battleMultiplier(type,defender.mon);if(battleAbilitySlug(attacker)==='scrappy'&&defender.mon.types.includes(8)&&[1,2].includes(type))multiplier=Math.max(1,multiplier);if(!breaker&&ability==='wonder-guard'&&multiplier<=1)return 0;return multiplier;}
function battleStatValue(fighter,key){const indexes={atk:1,def:2,spa:3,spd:4},value=fighter.mon.stats[indexes[key]]*battleStageMultiplier(fighter.stages[key]),ability=battleAbilitySlug(fighter);let result=value;if(key==='atk'&&['huge-power','pure-power'].includes(ability))result*=2;if(key==='atk'&&ability==='hustle')result*=1.5;if(key==='atk'&&ability==='guts'&&fighter.status)result*=1.5;if(key==='atk'&&ability==='toxic-boost'&&fighter.status===5)result*=1.5;if(key==='spa'&&ability==='flare-boost'&&fighter.status===4)result*=1.5;if(key==='spa'&&ability==='solar-power'&&battleField.weather==='sol')result*=1.5;if(['atk','spa'].includes(key)&&ability==='defeatist'&&fighter.hp<=fighter.maxHp/2)result*=.5;if(key==='atk'&&ability==='slow-start'&&fighter.slowStart>0)result*=.5;if(key==='def'&&ability==='fur-coat')result*=2;if(key==='def'&&ability==='marvel-scale'&&fighter.status)result*=1.5;if(key==='spd'&&ability==='ice-scales')result*=2;return Math.max(1,result);}
function offensiveAbilityMultiplier(attacker,move,effect){const ability=battleAbilitySlug(attacker),type=battleMoveType(attacker,move);let value=1;if(ability==='technician'&&move.power<=60)value*=1.5;if(ability==='tinted-lens'&&effect>0&&effect<1)value*=2;if(['blaze','torrent','overgrow','swarm'].includes(ability)&&attacker.hp<=attacker.maxHp/3&&({blaze:10,torrent:11,overgrow:12,swarm:7})[ability]===type)value*=1.5;if(ability==='steelworker'&&type===9)value*=1.5;if(ability==='transistor'&&type===13)value*=1.5;if(ability==='dragons-maw'&&type===16)value*=1.5;if(ability==='rocky-payload'&&type===6)value*=1.5;if(ability==='iron-fist'&&move.key.includes('punch'))value*=1.2;if(ability==='strong-jaw'&&['bite','crunch','fang'].some(word=>move.key.includes(word)))value*=1.5;if(ability==='mega-launcher'&&['pulse','aura-sphere'].some(word=>move.key.includes(word)))value*=1.5;if(['aerilate','pixilate','refrigerate','galvanize'].includes(ability)&&move.type===1)value*=1.2;if(ability==='sheer-force'&&(move.ailmentChance||move.statChance||move.flinch))value*=1.3;if(ability==='adaptability'&&attacker.mon.types.includes(type))value*=4/3;if(ability==='water-bubble'&&type===11)value*=2;if(attacker.flashFireBoost&&type===10)value*=1.5;if(battleField.weather==='sol')value*=type===10?1.5:type===11?.5:1;if(battleField.weather==='lluvia')value*=type===11?1.5:type===10?.5:1;return value;}
function defensiveAbilityMultiplier(defender,move,effect,atFull){const ability=battleAbilitySlug(defender),type=move.type;let value=1;if(ability==='thick-fat'&&[10,15].includes(type))value*=.5;if(ability==='heatproof'&&type===10)value*=.5;if(ability==='water-bubble'&&type===10)value*=.5;if(ability==='dry-skin'&&type===10)value*=1.25;if(ability==='fluffy'){if(move.category==='physical')value*=.5;if(type===10)value*=2;}if(['filter','solid-rock','prism-armor'].includes(ability)&&effect>1)value*=.75;if(['multiscale','shadow-shield'].includes(ability)&&atFull)value*=.5;if(ability==='punk-rock'&&['sound','voice','song','boomburst','snarl'].some(word=>move.key.includes(word)))value*=.5;return value;}
function battleMovePower(attacker,defender,move){if(move.power)return move.key==='facade'&&attacker.status?move.power*2:move.key==='hex'&&defender.status?move.power*2:move.key==='venoshock'&&defender.status===5?move.power*2:move.key==='brine'&&defender.hp<=defender.maxHp/2?move.power*2:move.key==='acrobatics'?move.power*2:move.key==='eruption'||move.key==='water-spout'?Math.max(1,Math.floor(move.power*attacker.hp/attacker.maxHp)):move.power;if(['seismic-toss','night-shade'].includes(move.key))return 50;if(move.key==='dragon-rage')return 40;if(move.key==='sonic-boom')return 20;if(['grass-knot','low-kick'].includes(move.key)){const weight=defender.mon.weight;return weight>=2000?120:weight>=1000?100:weight>=500?80:weight>=250?60:weight>=100?40:20;}if(['heavy-slam','heat-crash'].includes(move.key)){const ratio=attacker.mon.weight/Math.max(1,defender.mon.weight);return ratio>=5?120:ratio>=4?100:ratio>=3?80:ratio>=2?60:40;}if(move.key==='gyro-ball')return Math.min(150,Math.max(1,Math.floor(25*effectiveBattleSpeed(defender)/Math.max(1,effectiveBattleSpeed(attacker))+1)));if(move.key==='electro-ball'){const ratio=effectiveBattleSpeed(attacker)/Math.max(1,effectiveBattleSpeed(defender));return ratio>=4?150:ratio>=3?120:ratio>=2?80:ratio>1?60:40;}if(['flail','reversal'].includes(move.key)){const ratio=attacker.hp/attacker.maxHp;return ratio<=.04?200:ratio<=.1?150:ratio<=.2?100:ratio<=.35?80:ratio<=.69?40:20;}if(move.key==='stored-power'||move.key==='power-trip')return 20+20*Object.values(attacker.stages).filter(value=>value>0).reduce((sum,value)=>sum+value,0);return 60;}
function calculateDamage(attacker,defender,move){const type=battleMoveType(attacker,move),effect=effectiveMultiplier(attacker,defender,move);if(effect===0)return{damage:0,effect,type};const attackKey=move.key==='body-press'?'def':move.key==='foul-play'?'atk':move.category==='special'?'spa':'atk',atk=move.key==='foul-play'?battleStatValue(defender,'atk'):battleStatValue(attacker,attackKey),def=battleStatValue(defender,move.category==='special'?'spd':'def'),power=battleMovePower(attacker,defender,move),actualMove=power===move.power?move:{...move,power},stab=attacker.mon.types.includes(type)?1.5:1,variance=.9+activeRandom()*.1,boost=gameDifficulty==='expert'&&battleEnemy.includes(attacker)?1.08:1,burn=attacker.status===4&&move.category==='physical'&&battleAbilitySlug(attacker)!=='guts'?.5:1;let damage=Math.max(1,Math.round((((22*power*atk/def)/50)+2)*stab*effect*offensiveAbilityMultiplier(attacker,actualMove,effect)*defensiveAbilityMultiplier(defender,actualMove,effect,defender.hp===defender.maxHp)*variance*boost*burn));if(battleAbilitySlug(defender)==='sturdy'&&defender.hp===defender.maxHp&&damage>=defender.hp)damage=defender.hp-1;return{damage,effect,type};}
function moveExpected(attacker,defender,move){if(move.category==='status')return move.healing||move.changes.length?30:8;const hit=calculateDamage(attacker,defender,move);return hit.damage*(move.accuracy||100)/100;}
function aiMove(enemy,player){if(gameDifficulty==='easy')return enemy.moves[Math.floor(activeRandom()*enemy.moves.length)];return [...enemy.moves].sort((a,b)=>moveExpected(enemy,player,b)-moveExpected(enemy,player,a))[0];}

function setBattleStatus(target,ailment,source){if(!BATTLE_AILMENTS[ailment]||target.status)return;const immunities={4:[10],5:[4,9],1:[13],3:[15]},ability=battleAbilitySlug(target),abilityBlocks={1:['limber'],2:['insomnia','vital-spirit'],3:['magma-armor'],4:['water-veil','water-bubble'],5:['immunity']};if(immunities[ailment]?.some(type=>target.mon.types.includes(type))||abilityBlocks[ailment]?.includes(ability))return;target.status=ailment;target.statusTurns=ailment===2?Math.floor(activeRandom()*3)+1:0;battleLog.push(`${target.mon.name} quedó ${BATTLE_AILMENTS[ailment]} por ${source}.`);}
function applyMoveChanges(attacker,defender,move){if(battleAbilitySlug(attacker)==='sheer-force')return;const target=[7,8,12,13,14].includes(move.target)?attacker:defender,grace=battleAbilitySlug(attacker)==='serene-grace'?2:1,chance=Math.min(100,(move.statChance||100)*grace);if(battleChance(chance))move.changes.forEach(([stat,change])=>changeBattleStage(target,BATTLE_STAT_KEYS[stat],change,move.name));if(battleAbilitySlug(defender)!=='shield-dust'&&move.ailment&&battleChance(Math.min(100,(move.ailmentChance||move.effectChance||100)*grace)))setBattleStatus(defender,move.ailment,move.name);}
function absorbBattleMove(defender,move){const ability=battleAbilitySlug(defender);if(['volt-absorb','water-absorb','dry-skin'].includes(ability)){const amount=Math.round(defender.maxHp/4);defender.hp=Math.min(defender.maxHp,defender.hp+amount);battleLog.push(`${battleAbilityName(defender.abilityId)} anuló ${move.name} y recuperó ${amount} PS.`);}else if(['lightning-rod','storm-drain'].includes(ability)){changeBattleStage(defender,'spa',1,battleAbilityName(defender.abilityId));battleLog.push(`${battleAbilityName(defender.abilityId)} anuló ${move.name}.`);}else if(ability==='motor-drive'){changeBattleStage(defender,'spe',1,battleAbilityName(defender.abilityId));battleLog.push(`${battleAbilityName(defender.abilityId)} anuló ${move.name}.`);}else if(ability==='sap-sipper'){changeBattleStage(defender,'atk',1,battleAbilityName(defender.abilityId));battleLog.push(`${battleAbilityName(defender.abilityId)} anuló ${move.name}.`);}else{if(ability==='flash-fire')defender.flashFireBoost=true;battleLog.push(`${battleAbilityName(defender.abilityId)} anuló ${move.name}.`);}}
function accuracyHits(attacker,defender,move){if(!move.accuracy||[battleAbilitySlug(attacker),battleAbilitySlug(defender)].includes('no-guard'))return true;let accuracy=move.accuracy*battleStageMultiplier(attacker.stages.acc-defender.stages.eva);if(battleAbilitySlug(attacker)==='compound-eyes')accuracy*=1.3;if(battleAbilitySlug(attacker)==='hustle'&&move.category==='physical')accuracy*=.8;if((battleAbilitySlug(defender)==='sand-veil'&&battleField.weather==='tormenta de arena')||(battleAbilitySlug(defender)==='snow-cloak'&&battleField.weather==='nieve'))accuracy*=.8;return battleChance(Math.min(100,accuracy));}
function canBattleAct(fighter){if(fighter.recharging){fighter.recharging=false;battleLog.push(`${fighter.mon.name} necesita recargar energía.`);return false;}if(fighter.flinched){fighter.flinched=false;battleLog.push(`${fighter.mon.name} retrocedió y no pudo moverse.`);return false;}if(fighter.status===2){if(fighter.statusTurns>0){fighter.statusTurns--;battleLog.push(`${fighter.mon.name} está dormido.`);return false;}fighter.status=null;battleLog.push(`${fighter.mon.name} se despertó.`);}if(fighter.status===3){if(!battleChance(20)){battleLog.push(`${fighter.mon.name} está congelado.`);return false;}fighter.status=null;battleLog.push(`${fighter.mon.name} se descongeló.`);}if(fighter.status===1&&battleChance(25)){battleLog.push(`${fighter.mon.name} está paralizado y no se puede mover.`);return false;}return true;}
function useBattleMove(attacker,defender,move){if(!canBattleAct(attacker))return;if(!accuracyHits(attacker,defender,move)){battleLog.push(`${attacker.mon.name} usó ${move.name}, pero falló.`);return;}battleLog.push(`${attacker.mon.name} usó ${move.name}.`);if(['protect','detect','kings-shield','spiky-shield','baneful-bunker','silk-trap','burning-bulwark'].includes(move.key)){attacker.protected=true;battleLog.push(`${attacker.mon.name} se protegió.`);return;}if(move.key==='trick-room'){battleField.trickRoom=5;battleLog.push('¡Se alteró el orden de Velocidad!');return;}if(['rain-dance','sunny-day','sandstorm','snowscape','hail'].includes(move.key)){battleField.weather={'rain-dance':'lluvia','sunny-day':'sol',sandstorm:'tormenta de arena',snowscape:'nieve',hail:'nieve'}[move.key];battleLog.push(`El clima cambió a ${battleField.weather}.`);return;}if(defender.protected){battleLog.push(`${defender.mon.name} se protegió del ataque.`);return;}if(move.healing>0){const amount=Math.max(1,Math.round(attacker.maxHp*move.healing/100));attacker.hp=Math.min(attacker.maxHp,attacker.hp+amount);battleLog.push(`${attacker.mon.name} recuperó ${amount} PS.`);}if(move.category==='status'){applyMoveChanges(attacker,defender,move);if(!move.healing&&!move.changes.length&&!move.ailment)battleLog.push(`${move.name} no produce otro efecto en esta batalla corta.`);return;}const hit=calculateDamage(attacker,defender,move);if(hit.effect===0){absorbBattleMove(defender,move);return;}const hits=move.minHits?move.minHits+Math.floor(activeRandom()*(move.maxHits-move.minHits+1)):1;hit.damage*=hits;defender.hp=Math.max(0,defender.hp-hit.damage);battleLog.push(`${hit.damage} de daño${hits>1?` en ${hits} golpes`:''}.${hit.effect>1?' ¡Es supereficaz!':hit.effect<1?' No es muy eficaz.':''}`);if(move.drain>0){const amount=Math.max(1,Math.round(hit.damage*move.drain/100));attacker.hp=Math.min(attacker.maxHp,attacker.hp+amount);battleLog.push(`${attacker.mon.name} absorbió ${amount} PS.`);}if(move.drain<0&& !['rock-head','magic-guard'].includes(battleAbilitySlug(attacker))){const amount=Math.max(1,Math.round(hit.damage*Math.abs(move.drain)/100));attacker.hp=Math.max(0,attacker.hp-amount);battleLog.push(`${attacker.mon.name} recibió ${amount} PS de retroceso.`);}if(defender.hp>0){applyMoveChanges(attacker,defender,move);if(move.flinch&&battleAbilitySlug(defender)!=='inner-focus'&&battleAbilitySlug(defender)!=='shield-dust'&&battleChance(Math.min(100,move.flinch*(battleAbilitySlug(attacker)==='serene-grace'?2:1))))defender.flinched=true;}if(['hyper-beam','giga-impact','blast-burn','frenzy-plant','hydro-cannon','roar-of-time','rock-wrecker'].includes(move.key))attacker.recharging=true;if(defender.hp<=0){battleLog.push(`¡${defender.mon.name} quedó fuera de combate!`);if(battleAbilitySlug(attacker)==='moxie')changeBattleStage(attacker,'atk',1,'Autoestima');}}
async function animateBattleAction(owner,move){
 const scene=document.querySelector('.battle-scene'),attacker=document.querySelector(`.battle-side.${owner} .battle-platform img`),target=document.querySelector(`.battle-side.${owner==='player'?'enemy':'player'} .battle-platform img`),banner=document.querySelector('.battle-action-banner');
 if(banner){banner.hidden=false;banner.textContent=`${owner==='player'?'Tu Pokémon':'El rival'} usa ${move.name}`;banner.className=`battle-action-banner type-${move.type}`;}
 if(!scene||!attacker){await battleWait(500);return;}
 scene.classList.add('battle-cinematic',`battle-from-${owner}`,`battle-kind-${move.category}`);scene.dataset.attackType=String(move.type);attacker.classList.add(move.category==='status'?'battle-cast':'battle-windup');
 if(move.category==='status'||move.healing){const aura=document.createElement('span');aura.className=`battle-aura type-${move.type}`;aura.setAttribute('aria-hidden','true');attacker.closest('.battle-platform')?.append(aura);await battleWait(620);attacker.classList.add('battle-heal');return;}
 await battleWait(150);attacker.classList.add('battle-attack');
 if(move.category==='special'){const projectile=document.createElement('span');projectile.className=`battle-projectile type-${move.type}`;projectile.setAttribute('aria-hidden','true');scene.append(projectile);requestAnimationFrame(()=>projectile.classList.add('is-flying'));await battleWait(330);}else await battleWait(230);
 target?.classList.add('battle-hit');scene.classList.add('battle-camera-hit');const burst=document.createElement('span');burst.className=`battle-impact-burst type-${move.type}`;burst.setAttribute('aria-hidden','true');target?.closest('.battle-platform')?.append(burst);await battleWait(360);
}
async function animateBattleFaint(owner){const target=document.querySelector(`.battle-side.${owner==='player'?'enemy':'player'} .battle-platform img`);if(!target)return;target.classList.remove('battle-hit');target.classList.add('battle-faint');await battleWait(520);}
async function executeBattleAction(attacker,defender,move,owner){if(attacker.hp<=0||defender.hp<=0)return;await animateBattleAction(owner,move);useBattleMove(attacker,defender,move);if(defender.hp<=0)await animateBattleFaint(owner);renderBattle();await battleWait(520);}
function endTurnEffects(){[...battlePlayer,...battleEnemy].filter(fighter=>fighter.hp>0).forEach(fighter=>{const ability=battleAbilitySlug(fighter),indirectBlocked=ability==='magic-guard';if(fighter.status===5){const amount=Math.max(1,Math.floor(fighter.maxHp/8));if(ability==='poison-heal'){fighter.hp=Math.min(fighter.maxHp,fighter.hp+amount);battleLog.push(`${fighter.mon.name} recuperó ${amount} PS gracias a Antídoto.`);}else if(!indirectBlocked){fighter.hp=Math.max(0,fighter.hp-amount);battleLog.push(`${fighter.mon.name} perdió ${amount} PS por el veneno.`);}}if(fighter.status===4&&!indirectBlocked){const amount=Math.max(1,Math.floor(fighter.maxHp/16));fighter.hp=Math.max(0,fighter.hp-amount);battleLog.push(`${fighter.mon.name} perdió ${amount} PS por la quemadura.`);}if((ability==='rain-dish'&&battleField.weather==='lluvia')||(ability==='ice-body'&&battleField.weather==='nieve')||(ability==='dry-skin'&&battleField.weather==='lluvia')){const amount=Math.max(1,Math.floor(fighter.maxHp/(ability==='dry-skin'?8:16)));fighter.hp=Math.min(fighter.maxHp,fighter.hp+amount);battleLog.push(`${fighter.mon.name} recuperó ${amount} PS gracias a ${battleAbilityName(fighter.abilityId)}.`);}if((ability==='dry-skin'||ability==='solar-power')&&battleField.weather==='sol'&&!indirectBlocked){const amount=Math.max(1,Math.floor(fighter.maxHp/8));fighter.hp=Math.max(0,fighter.hp-amount);battleLog.push(`${fighter.mon.name} perdió ${amount} PS por ${battleAbilityName(fighter.abilityId)}.`);}if(ability==='hydration'&&battleField.weather==='lluvia'&&fighter.status){fighter.status=null;battleLog.push(`${fighter.mon.name} se curó gracias a Hidratación.`);}if(ability==='shed-skin'&&fighter.status&&battleChance(33)){fighter.status=null;battleLog.push(`${fighter.mon.name} se curó gracias a Mudar.`);}if(ability==='speed-boost')changeBattleStage(fighter,'spe',1,'Impulso');if(fighter.slowStart>0)fighter.slowStart--;});if(battleField.trickRoom>0)battleField.trickRoom--;}
async function playBattleTurn(moveIndex){if(battleBusy||battleFinished)return;battleBusy=true;const player=battlePlayer[battlePlayerActive],enemy=battleEnemy[battleEnemyActive];player.protected=false;enemy.protected=false;renderBattle();const playerMove=player.moves[moveIndex],enemyMove=aiMove(enemy,player),playerPriority=battleMovePriority(player,playerMove),enemyPriority=battleMovePriority(enemy,enemyMove),playerSpeed=effectiveBattleSpeed(player),enemySpeed=effectiveBattleSpeed(enemy);let playerFirst;if(playerPriority!==enemyPriority)playerFirst=playerPriority>enemyPriority;else if(playerSpeed===enemySpeed)playerFirst=activeRandom()<.5;else playerFirst=battleField.trickRoom?playerSpeed<enemySpeed:playerSpeed>enemySpeed;battleLog.push(playerPriority!==enemyPriority?`${playerFirst?player.mon.name:enemy.mon.name} tiene prioridad.`:`${playerFirst?player.mon.name:enemy.mon.name} ataca primero por Velocidad (${Math.round(playerFirst?playerSpeed:enemySpeed)}).`);renderBattle();const sequence=playerFirst?[[player,enemy,playerMove,'player'],[enemy,player,enemyMove,'enemy']]:[[enemy,player,enemyMove,'enemy'],[player,enemy,playerMove,'player']];for(const action of sequence)await executeBattleAction(...action);endTurnEffects();afterBattleTurn();}
async function switchBattlePokemon(index){if(battleBusy||index===battlePlayerActive||battlePlayer[index]?.hp<=0)return;battleBusy=true;const old=battlePlayer[battlePlayerActive];if(battleAbilitySlug(old)==='natural-cure')old.status=null;if(battleAbilitySlug(old)==='regenerator')old.hp=Math.min(old.maxHp,old.hp+Math.floor(old.maxHp/3));battlePlayerActive=index;const incoming=battlePlayer[index],enemy=battleEnemy[battleEnemyActive];battleLog.push(`Retiraste a ${old.mon.name}. ¡Adelante, ${incoming.mon.name}!`);applyEntryAbility(incoming,enemy);renderBattle();await battleWait(520);await executeBattleAction(enemy,incoming,aiMove(enemy,incoming),'enemy');endTurnEffects();afterBattleTurn();}
function nextAlive(team){return team.findIndex(fighter=>fighter.hp>0);}
function afterBattleTurn(){if(battleEnemy[battleEnemyActive].hp<=0){const next=nextAlive(battleEnemy);if(next<0){finishBattle(true);return;}battleEnemyActive=next;battleLog.push(`El líder ${battleLeader.name} envía a ${battleEnemy[next].mon.name}.`);applyEntryAbility(battleEnemy[next],battlePlayer[battlePlayerActive]);}if(battlePlayer[battlePlayerActive].hp<=0){const next=nextAlive(battlePlayer);if(next<0){finishBattle(false);return;}battlePlayerActive=next;battleLog.push(`¡${battlePlayer[next].mon.name}, es tu turno!`);applyEntryAbility(battlePlayer[next],battleEnemy[battleEnemyActive]);}battleTurn++;battleBusy=false;renderBattle();}
function finishBattle(won){battleFinished=true;battleBusy=false;score=won?1000:0;typeof markDailyPlayed==='function'&&markDailyPlayed('battle',won);$('score').textContent=String(score).padStart(3,'0');$('progress').textContent=won?'MEDALLA CONSEGUIDA':'EQUIPO DERROTADO';const star=won?battlePlayer[battlePlayerActive]?.mon:battleEnemy[battleEnemyActive]?.mon;$('game').innerHTML=`<div class="result battle-result">${star?monImage(star):''}<span class="eyebrow">${won?'VICTORIA DE GIMNASIO':'FIN DEL COMBATE'}</span><h3>${won?`¡Venciste al líder ${battleEsc(battleLeader.name)}!`:`El líder ${battleEsc(battleLeader.name)} ganó esta vez`}</h3><p>${won?'Tu estrategia te dio una nueva medalla.':'Cambiá tu equipo y aprovechá las habilidades, movimientos y ventajas de tipo.'}</p><div class="gym-badge" data-type="${battleLeader.type}">◆</div></div>`;$('feedback').replaceChildren();}
const startBeforeBattle=start;start=function(game){if(game!=='battle')return startBeforeBattle(game);clearTimeout(timeout);clearInterval(clock);if($('grid-dialog').open)$('grid-dialog').close();current=game;score=0;battleLog=[];$('feedback').replaceChildren();$('pool-count').textContent=`${eligible().length} Pokémon disponibles`;document.querySelectorAll('[data-game]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.game===game)));renderBattleSetup();if(typeof syncGenerations==='function')syncGenerations();};
